async function loadWebTools(){
 if(!repoRoot)return[];
 try{
  const registry=JSON.parse(await readFile(join(repoRoot,'src/mm530/mm530-registry.json'),'utf8')).tools||[];
  if(registry.length!==530)throw Error('Expected 530 web-tool registry rows.');
  return await Promise.all(registry.map(async t=>{
   let description='';
   try{
    const html=await readFile(join(repoRoot,t.sourceDir,'page.html'),'utf8');
    const tag=html.match(/<meta\b[^>]*name=["']description["'][^>]*>/i)?.[0]||'';
    description=decodeMeta(tag.match(/content="([^"]*)"/i)?.[1]??tag.match(/content='([^']*)'/i)?.[1]??'');
   }catch{}
   description=cleanPublicText(description)||`Use ${t.title} directly in your browser with local-first processing and clearly stated inputs.`;
   return {...t,description};
  }));
 }catch(error){console.warn('Advanced web-tool registry unavailable:',error instanceof Error?error.message:String(error));return[]}
}
