await page('/chordlibrary/',{title:'Chord library for distinctive tunings',description:'Find complete chord voicings for mandolin, bouzouki, charango, cavaquinho, baritone ukulele, tenor banjo and alternate guitar tunings.',cat:'chordlibrary',body:`${search('Search instruments or tunings')}<div class="grid">${INSTRUMENTS.map(i=>card(url('chordlibrary',i.id),i.name,i.courses,'Browse chords')).join('')}</div><section class="section prose"><h2>How this library finds shapes</h2><p>For each open-string tuning, a music-theory engine searches frets 0–12 for all the required chord tones. It excludes non-chord tones and keeps a compact fret span. Muted courses and open courses are shown explicitly.</p><p>A theoretically correct voicing still needs a practical fingering. Hand size, barre technique and the instrument setup affect playability. Audio is a synthesized pitch preview, not an instrument recording; doubled courses are represented by one pitch.</p></section>`});
let omitted=0;
for(const inst of INSTRUMENTS){const links=[];for(const rootNote of ROOTS)for(const [quality,q] of Object.entries(QUALITIES)){const shapes=voicings(inst.tuning,rootNote[2],quality);if(!shapes.length){omitted++;continue;}const id=`${inst.id}/${rootNote[0]}-${quality}`,title=`${rootNote[1]} ${q.name} on ${inst.name}`,names=chordNotes(rootNote,quality),geo=`Chord tones: ${names.join(', ')}. Intervals from the root: ${q.intervals.join(', ')} semitones.`,intro=`${title}: ${names.join('–')} chord tones, complete fingering diagrams, open tuning ${inst.tuning.map(midiName).join('–')}, audio and a printable chord sheet.`;links.push({id,title,description:names.join(' · ')});const htmlShapes=shapes.map((v,i)=>`<article class="voicing">${diagram(v.frets,inst.tuning,`${rootNote[1]} ${q.name} · ${i+1}`)}<p>Frets: ${v.frets.map(f=>f<0?'mute':f).join(' · ')}<br>Sounding pitches: ${v.notes.map(midiName).join(', ')}</p></article>`).join('');await page(`/chordlibrary/${id}/`,{title,description:intro,cat:'chordlibrary',config:{kind:'chord',id,instrument:inst,root:rootNote,quality},body:`<p class="formula">${esc(geo)}</p><div class="workspace section"><form id="tool-form" class="panel"><p class="eyebrow">VOICING SEARCH</p><div class="fields">${field({key:'maxFret',label:'Maximum fret',value:12,min:1,max:18,step:1})}${field({key:'maxSpan',label:'Maximum fret span',value:4,min:1,max:5,step:1})}</div>${buttons}<p class="small">Each required chord tone must sound at least once. Muting is allowed; note omissions are not.</p><div class="actions"><button id="download-chords" type="button" class="secondary">Download chord diagram PDF</button></div></form><div><div id="voicings" class="chord-grid">${htmlShapes}</div></div></div><section class="section prose"><h2>Reading these ${esc(rootNote[1])} ${esc(q.name)} shapes</h2><p>Courses run left to right in this tuning: ${esc(inst.tuning.map(midiName).join(', '))}. A circle above the nut means open; a cross means mute. Numbers inside the dots are fret numbers, not finger numbers. A fret label at the side marks shapes higher up the neck.</p><p>${esc(inst.courses)}</p><h3>Why these notes?</h3><p>${esc(geo)} Chord tone spellings follow the chord degrees; sounding-pitch labels may use an enharmonic equivalent.</p><h3>Does every shape use the root in the bass?</h3><p>No. Complete inversions are included, with root-bass shapes preferred when otherwise similar. In re-entrant tuning, the leftmost course may not be the lowest sounding pitch.</p><p>Shapes are ranked by fret height, fret span, muting and bass note. Check barre feasibility before playing. The synthesized preview represents pitches only, without doubled or octave-paired strings.</p></section><section class="section"><h2>More chords in this tuning</h2><div class="linklist">${ROOTS.map(r=>`<a href="${url('chordlibrary',inst.id+'/'+r[0]+'-major')}">${esc(r[1])} major</a>`).join('')}</div><div class="actions"><a class="button secondary" href="${url('chordlibrary',inst.id)}">All ${esc(inst.name)} chords</a></div></section>`});}
await page(`/chordlibrary/${inst.id}/`,{title:`${inst.name} chord collection`,description:`Browse ${links.length} complete chords for ${inst.name}, with open pitches ${inst.tuning.map(midiName).join(', ')}. ${inst.courses}`,cat:'chordlibrary',body:`${search('Search chord names')}<div class="grid">${links.map(l=>card(url('chordlibrary',l.id),l.title,l.description,'View diagrams')).join('')}</div>`});}
