await page('/fontconverters/',{title:'Legacy text to modern Unicode',description:'Recover searchable text from Kruti Dev, Bijoy, FM Abhaya, Bamini and Zawgyi encodings. Six conversion directions, processed on your device.',cat:'fontconverters',body:`<div class="grid">${ENCODINGS.map(e=>card(url('fontconverters',e.id),e.name,e.note,'Open converter')).join('')}</div><section class="section prose"><h2>Choose the original encoding</h2><p>Legacy text often looks like Latin characters until the original font is applied. The converter must match that encoding; changing the display font alone does not recover Unicode text.</p><p>Paste only the text run encoded in the chosen font. Mixed English and legacy text can be ambiguous because the same ASCII characters are used for both. Plain text files are supported. PDF extraction, OCR and Word font-run detection are separate tasks.</p></section>`});
for(const e of ENCODINGS)await page(`/fontconverters/${e.id}/`,{title:e.name,description:e.note,cat:'fontconverters',config:{kind:'font',id:e.id},body:`<div class="panel"><div class="font-layout"><div class="editor-source"><p class="editor-kicker">01 / ORIGINAL</p><label for="source-text">Source text in the selected encoding</label><textarea id="source-text" maxlength="100000" spellcheck="false" placeholder="Paste only the legacy-font text run here"></textarea></div><div class="editor-output"><p class="editor-kicker">02 / CONVERTED</p><label for="output-text">Converted output</label><textarea id="output-text" readonly spellcheck="false" aria-live="polite" placeholder="Converted text appears here"></textarea></div></div><div class="actions"><button id="convert" type="button">Convert text</button><button id="sample" type="button" class="secondary">Try a sample</button><button id="clear" type="button" class="secondary">Clear</button><button id="copy" type="button" class="secondary">Copy output</button><button id="download-text" type="button" class="secondary">Download TXT</button></div><p id="error" class="error" role="alert" hidden></p><p id="char-count" class="small" aria-live="polite"></p><pre id="conversion-warnings" class="error" style="white-space:pre-wrap" aria-live="polite"></pre><div class="fields section"><div><label for="text-file">Import a plain text file (.txt)</label><input id="text-file" type="file" accept=".txt,text/plain"></div><div><label for="file-encoding">File byte encoding</label><select id="file-encoding"><option value="utf-8">UTF-8</option><option value="windows-1252">Windows-1252 / legacy ANSI</option></select></div></div></div><section class="section prose"><h2>How to convert ${esc(e.script)} text</h2><ol><li>Select and copy the original font run from the document.</li><li>Paste it above and press Convert text.</li><li>Compare names, numbers and conjuncts with the original visual document.</li><li>Copy the output or save a UTF-8 text file.</li></ol><h3>Example</h3><p class="formula">${esc(e.sample)} → ${esc(e.expected)}</p><h3>What this tool preserves</h3><p>Conversion targets character encoding rather than page formatting. Text is processed locally, with no upload, no automatic storage and no account requirement. Keep your original document as a reference.</p><h3>Limitations</h3><p>${esc(e.note)} Conversion is not guaranteed to be lossless. The plain-text importer cannot identify font runs. Ambiguous symbols and extraction errors require review.</p></section><p class="small">Open-source mapping credits and license texts are listed on <a href="${BASE}/methodology/">Methods & sources</a>. Proprietary font binaries are not distributed.</p>`});
await page('/printablepaper/',{title:'Printable paper studio',description:'Design eight types of printable paper with exact page sizes, millimetre spacing, margins, line weight and colour. Export vector PDF or SVG.',cat:'printablepaper',body:`<div class="grid">${PAPER_TYPES.map(([id,name,note])=>card(url('printablepaper',id),name,note,'Design paper')).join('')}</div><section class="section prose"><h2>Print at actual size</h2><p>Downloads are vector drawings. Select actual size or 100% in your print dialog to preserve spacing. Fit-to-page changes millimetres. Printer non-printable margins can clip designs if the selected margin is too small.</p><p>Graph and dot spacing measures adjacent guides. Hex spacing is the distance between opposite flat sides. Music spacing is the distance between staff lines; handwriting spacing is the distance from upper guide to baseline.</p></section>`});
for(const [id,name,note] of PAPER_TYPES){const defaults={size:'a4',orientation:'portrait',spacing:id==='music'?2.5:id==='handwriting'?8:id==='planner'?10:5,margin:10,color:'#9aa8a0',weight:.2,opacity:1};await page(`/printablepaper/${id}/`,{title:`${name} generator`,description:`${note} Customize A4, A5 or US Letter pages and download a vector PDF or SVG.`,cat:'printablepaper',config:{kind:'paper',id},body:`<div class="workspace"><form id="tool-form" class="panel"><p class="eyebrow">PAGE SETTINGS</p><div class="fields"><div><label for="size">Page size</label><select id="size" name="size"><option value="a4">A4 · 210 × 297 mm</option><option value="letter">US Letter · 8.5 × 11 in</option><option value="a5">A5 · 148 × 210 mm</option></select></div><div><label for="orientation">Orientation</label><select id="orientation" name="orientation"><option value="portrait">Portrait</option><option value="landscape">Landscape</option></select></div>${field({key:'spacing',label:id==='hex'?'Flat-to-flat spacing (mm)':'Guide spacing (mm)',value:defaults.spacing,min:2,max:50})}${field({key:'margin',label:'Page margin (mm)',value:10,min:5,max:40})}${field({key:'weight',label:'Line / dot weight (mm)',value:.2,min:.05,max:1})}<div><label for="color">Line colour</label><input id="color" name="color" type="color" value="#9aa8a0"></div>${field({key:'opacity',label:'Colour opacity (0.1–1)',value:1,min:.1,max:1,step:.1})}</div><div class="actions"><button type="submit">Update preview</button><button type="reset" class="secondary">Reset</button></div><p id="error" class="error" role="alert" hidden></p><div class="actions"><button id="download-pdf" type="button">Download PDF</button><button id="download-svg" type="button" class="secondary">Download SVG</button></div><p class="small">Use actual size / 100% when printing. The PDF is drawn at exact page dimensions.</p></form><div class="paper-stage"><div class="stage-heading"><span class="eyebrow">YOUR CANVAS</span><span class="canvas-dot"></span></div><p id="paper-summary" class="small" aria-live="polite">A4 preview</p><div id="paper-preview" class="paper-preview">${svg(drawing(id,defaults))}</div></div></div><section class="section prose"><h2>About this ${name.toLowerCase()}</h2><p>${esc(note)} Lines and dots are generated from your selected physical spacing. The PDF preserves vector geometry, so it does not need a high-resolution image.</p><h3>Spacing conventions</h3><p>Square and dot paper use the distance between adjacent guides. Hexagonal paper uses flat-to-flat distance. Music uses staff-line spacing, handwriting uses full guide height, and planner spacing sets horizontal task slots.</p><h3>Printer settings</h3><p>Select the matching paper size and print at 100%. Disable browser headers and footers if printing the page. Downloading the PDF gives the cleanest output.</p></section>`});}
await page('/methodology/',{title:'Methods, sources & limitations',description:'How Aafnai advanced tools calculate results, protect your inputs and use openly licensed conversion mappings.',body:`<section class="prose"><h2>Original calculation and drawing engines</h2><p>Knitting formulas use measured gauge, geometric fabric area and entered yarn labels. Yarn category and tool size labels are references, not interchangeable yarn recommendations. <a href="https://www.craftyarncouncil.com/standards/hooks-and-needles">Craft Yarn Council: sizing conventions</a>; <a href="https://www.craftyarncouncil.com/standards/faqs">swatch and substitution guidance</a>.</p><p>Chord shapes are calculated from semitone intervals and the explicitly listed tunings. The shapes contain every required pitch class; physical fingering is not certified. Audio is synthesized rather than recorded.</p><p>Workshop values use idealized 60-degree thread geometry. Cut-tap drill estimates differ from forming-tap pre-drills. We do not reproduce ISO/ANSI tolerance tables or claim certified fit classes. <a href="https://www.iso.org/standard/87889.html">ISO 965 tolerance-system scope</a>; <a href="https://videos.sandvik.coromant.com/solid-round-tools-session-9">Sandvik Coromant: cutting versus forming taps</a>.</p><p>Paper drawings are original vector geometry. PDF uses the Helvetica base font for labels; paper patterns do not embed proprietary font files.</p><h2>Conversion sources and licenses</h2>${table(['Mapping','Source','License'],[['Kruti Dev','ravitaak/krutidevtounicode','MIT; mapping adapted with guarded i/reph handling'],['Bijoy','JehadurRE/Bijoy2Unicode','MIT; vendored converter core'],['FM Abhaya','akuruAI/pandukabhaya','MIT mapping; proprietary font is not bundled'],['Bamini','Pakeetharan/unicode-bamini-converter','MIT; inverse map with ambiguity reporting'],['Zawgyi','google/myanmar-tools','Apache-2.0; generated conversion rules']])}<ul>${[['KrutiDev-MIT.txt','https://github.com/ravitaak/krutidevtounicode'],['Bijoy-LICENSE.txt','https://github.com/JehadurRE/Bijoy2Unicode'],['FM-Abhaya-MIT.txt','https://github.com/akuruAI/pandukabhaya'],['Bamini-MIT.txt','https://github.com/Pakeetharan/unicode-bamini-converter'],['Apache-2.0.txt','https://github.com/google/myanmar-tools']].map(([license,source])=>`<li><a href="${source}">${esc(source.split('github.com/')[1])}</a> · <a href="${BASE}/licenses/${license}">License text</a></li>`).join('')}</ul><h2>Privacy and accuracy</h2><p>These tools do not upload inputs or save pasted text. Downloads are made on your device. The parent website may have its own privacy policy and analytics; consult that policy separately.</p><p>Retain original documents and check consequential results. A correct formula can still give an unsuitable result when the input, model or assumed encoding is wrong.</p><h2>Version</h2><p>Module version 1.0.0. Methods and mapping sources reviewed 10 October 2026. See the downloadable implementation package for test coverage and source provenance.</p></section>`});
async function copyModules(dir,rel=''){for(const e of await readdir(dir,{withFileTypes:true})){const p=join(dir,e.name),r=join(rel,e.name);if(e.isDirectory())await copyModules(p,r);else if(e.name.endsWith('.mjs')||e.name==='style.css')await put('assets/'+assetVersion+'/'+r,await readFile(p));}}await copyModules(join(root,'src'));for(const name of await readdir(join(root,'licenses')))await put('licenses/'+name,await readFile(join(root,'licenses',name)));await put('downloads/gauge-worksheet.pdf',pdf(gaugeWorksheet()));
