let files=0,bytes=0;const hashes={};async function inventory(dir){for(const e of await readdir(dir,{withFileTypes:true})){const p=join(dir,e.name);if(e.isDirectory())await inventory(p);else{const b=await readFile(p);files++;bytes+=b.length;hashes[p.slice(out.length+1)]=createHash('sha256').update(b).digest('hex');}}}await inventory(out);const manifest={version:'1.0.0',origin,assetPrefix,pages:routes.length,omittedChordCombinations:omitted,files:files+1,bytes,counts:{knittingCalculators:KNITTING.length,knittingCharts:CHARTS.length,instrumentTunings:INSTRUMENTS.length,chordPages:routes.filter(x=>x.kind==='chord').length,threadPages:THREADS.length,workshopCalculators:WORKSHOP_TOOLS.length,fontDirections:ENCODINGS.length,paperTypes:PAPER_TYPES.length,webTools:MM530_TOOLS.length,clientTools:CLIENT_TOOLS.length,discoveryCategories:DISCOVERY_CATEGORIES.length},routes,hashes};await put('module-manifest.json',JSON.stringify(manifest,null,2)+'\n');await mkdir(join(root,'docs'),{recursive:true});await writeFile(join(root,'docs/build-summary.json'),JSON.stringify({...manifest,routes:undefined,hashes:undefined},null,2)+'\n');console.log(JSON.stringify({...manifest,routes:undefined,hashes:undefined},null,2));
